entries.command:
cd <repo> && for b in feat/1157-some-feature fix/some-fix-20260918 main; do
  f=$(git grep -c "if: failure()" origin/$b -- .github/workflows/ci.yml 2>/dev/null | cut -d: -f3); f=${f:-0}
  u=$(git grep -c "upload-artifact" origin/$b -- .github/workflows/ci.yml 2>/dev/null | cut -d: -f3); u=${u:-0}
  echo "  $b -> 'if: failure()'=$f   [CONTROL POSITIVO 'upload-artifact'=$u]"
done

echo "=== existe su recibo? ==="; ls -la "<repo>/.orquestador/recibos/" 2>/dev/null | grep -i t4 || echo "  no hay fichero T4"
echo "=== sus ultimos mensajes ==="
F="<tmp>/claude/<proyecto>/3b1f7c2e-9d4a-4e6b-a5c8-0f2d7e9b1a64/tasks/a7d2e4019bc3f5868.output"
tail -c 300000 "$F" | node -e "
let d='';process.stdin.on('data',c=>d+=c).on('end',()=>{const out=[];
for(const l of d.split('\n')){if(!l.trim().startsWith('{'))continue;let j;try{j=JSON.parse(l)}catch(e){continue}
const m=j.message;if(!m||m.role!=='assistant')continue;
for(const b of (m.content||[])) if(b.type==='text'&&b.text.trim()) out.push(b.text.trim());}
out.slice(-2).forEach(t=>console.log('---\n'+t.slice(0,700)));});"
